import six
from abc import ABCMeta, abstractmethod
from taf.ue.plugin.mtk.commands.at_command import EFUN
from taf.ue.plugin.mtk.flow.action_verifiable import ActionSequenceVerifiable
from taf.ue.plugin.mtk.flow.context_alias_store import ContextAliasStore


@six.add_metaclass(ABCMeta)
class Detach(ActionSequenceVerifiable):

    @abstractmethod
    def __init__(self, executor=None, verifier=None):
        self._executor = executor
        self._verifier = verifier

    def _generate_command_sequence(self):
        ContextAliasStore().release_all_context_ids()
        return [EFUN(self._executor, EFUN.Status.DISABLE)]

    def verify(self):
        if self._verifier:
            self._verifier.verify()


class NSADetach(Detach):

    def __init__(self, executor=None, verifier=None):
        super(NSADetach, self).__init__(executor=executor, verifier=verifier)


class SADetach(Detach):

    def __init__(self, executor=None, verifier=None):
        super(SADetach, self).__init__(executor=executor, verifier=verifier)


class LTEDetach(Detach):

    def __init__(self, executor=None, verifier=None):
        super(LTEDetach, self).__init__(executor=executor, verifier=verifier)
